/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: CandidatePairing
 * Internal
 *   Types: Position, Pairing, Step, Phase
 *   Functions: at, intent, definite, reload, clock
 *   Constants: integer, disc, track, duration, pairingSchema, changed, reread, said
 * @end-catalog */

import { useEffect, useId, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';
import { ApiError } from '../../api/client';
import { useLocalization } from '../../localization/LocalizationProvider';
import { useAdminAccess, useAdminText } from './AdminAccess';
import { ADMIN_IMPORT_RELOAD_REQUIRED, ADMIN_RELOAD_REQUIRED, adminEndpointRequest } from './adminTransport';
import styles from './adminStyles';

/**
 * Pairs each of an existing-Album review's members with a track of one release by hand: the options are the rows the member can
 * pair with (GET /catalog-reviews/:id/lookup/candidates/:key/pairing), closest duration first; a row another member took is
 * disabled; saving stores the chosen positions as the administrator's own Disc and Track Numbers through the review save (a Disc
 * Number only where the review captured one), which re-ranks, then chooses the release unless the re-rank applied it (owner rules,
 * next-step bullet). A failed choice keeps the saved numbers and offers choosing again alone. Its status says what is known: a
 * refusal, an outcome it could not confirm (sent again as the same operation), a reload request, or saved numbers that do not pair
 * the tracks with the release in exactly one way; while a save or choice runs, focus is on its heading. Its own chunk, loaded by
 * the candidate chooser on the review and import pages alike, so it imports only modules both already load: the review schemas,
 * its command hook and the summary query are not imported, and the few lines it needs of them are repeated here.
 */
const integer = z.number().int().nonnegative(), disc = z.number().int().min(1).max(999), track = z.number().int().min(1).max(9999);
const duration = z.number().int().positive().nullable();
type Position = { disc: number; track: number };
const at = (value: Position) => `${value.disc}:${value.track}`;
/** GET …/pairing, mirroring CatalogReviewPairingResponse (src/administration/lookup/lookupPairingView.ts); strict, as every own read. */
const pairingSchema = z.object({
  run: integer, revision: integer,
  rows: z.array(z.object({ disc, track, title: z.string().min(1).max(300), durationMs: duration }).strict()).max(100),
  members: z.array(z.object({ slotId: z.string().uuid(), title: z.string().max(300), durationMs: duration,
    saved: z.object({ disc: disc.nullable(), track: track.nullable() }).strict(), discSavable: z.boolean(),
    options: z.array(z.object({ disc, track, deltaMs: integer.nullable() }).strict()).max(100), forced: z.object({ disc, track }).strict().nullable() }).strict()).max(100)
}).strict().superRefine((value, ctx) => {
  const rows = new Set(value.rows.map(at));
  if (rows.size !== value.rows.length || new Set(value.members.map(member => member.slotId)).size !== value.members.length
    || value.members.some(member => member.options.some(option => !rows.has(at(option))) || (member.forced !== null && !rows.has(at(member.forced)))))
    ctx.addIssue({ code: 'custom', message: 'Invalid pairing read' });
});
type Pairing = z.infer<typeof pairingSchema>;
/** A change's answer as the panel reads it; the page reads the review again with its strict schema afterwards. */
const changed = z.object({ item: z.object({ id: z.string(), revision: integer }), receipt: z.object({ operationId: z.string() }) });
/** The lookup read after the save: only what deciding the choice needs. */
const reread = z.object({ lookup: z.object({ run: integer,
  applied: z.object({ run: integer, candidateKey: z.string().nullable(),
    pairs: z.array(z.object({ slotId: z.string(), discNumber: z.number(), trackNumber: z.number() })).nullable().optional() }).nullable(),
  candidates: z.array(z.object({ key: z.string(), comparison: z.object({ subset: z.object({ pairing: z.string().nullable() }).nullable().optional() }).nullable() })) }).nullable() });

type Step = { kind: 'save' | 'choose'; path: string; method: 'PATCH' | 'POST'; operationId: string; body: string };
type Phase = 'idle' | 'saving' | 'choosing' | 'saveFailed' | 'saveUnknown' | 'chooseFailed' | 'chooseUnknown' | 'notSingle' | 'reload';
/** Each phase's status message; idle says nothing. */
const said: Partial<Record<Phase, string>> = { saving: 'catalog_review.pairing_saving', choosing: 'catalog_review.pairing_choosing',
  saveFailed: 'catalog_review.pairing_save_failed', saveUnknown: 'catalog_review.pairing_save_unknown', chooseFailed: 'catalog_review.pairing_choose_failed',
  chooseUnknown: 'catalog_review.pairing_choose_unknown', notSingle: 'catalog_review.pairing_saved_not_single', reload: 'common.reload' };
const intent = (kind: Step['kind'], path: string, method: Step['method'], payload: object): Step => {
  const operationId = crypto.randomUUID(); return { kind, path, method, operationId, body: JSON.stringify({ ...payload, operationId }) };
};
/**
 * Whether a failure is a definite refusal, as AdminCommand reads it (useAdminCommand.ts): a reload request, a lookup refusal at any
 * status, or 400, 401, 403, 404, 409 or 422; a network failure, a 5xx, an unreadable answer or an abort leaves the outcome unknown.
 */
const definite = (error: unknown) => error instanceof ApiError && (error.code === ADMIN_RELOAD_REQUIRED || (error.kind === 'http'
  && (error.code === ADMIN_IMPORT_RELOAD_REQUIRED || /^ADMIN_IMPORT_LOOKUP_/.test(error.code ?? '') || [400, 401, 403, 404, 409, 422].includes(error.status ?? 0))));
/** A refusal that asks for a reload, which no retry on this page can pass. */
const reload = (error: unknown) => error instanceof ApiError && (error.code === ADMIN_RELOAD_REQUIRED || error.code === ADMIN_IMPORT_RELOAD_REQUIRED);
/** m:ss.cc, centiseconds rounded half up; a member's whole-second (legacy) duration as m:ss. */
const clock = (ms: number, member: boolean) => {
  const whole = member && ms % 1000 === 0, units = whole ? ms / 1000 : Math.round(ms / 10), seconds = whole ? units : Math.floor(units / 100);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}${whole ? '' : `.${String(units % 100).padStart(2, '0')}`}`;
};

export function CandidatePairing({ projectId, candidateKey, editions, run, title, disabled, onBusy, onClose }: {
  projectId: string; candidateKey: string;
  /** The keys of the card's editions: a re-rank that applied any of them through this pairing needs no choice. */
  editions: readonly string[];
  run: number;
  /** The release's title, for the heading. */
  title: string;
  /** The chooser's disabled state: nothing can be saved meanwhile. */
  disabled: boolean;
  /** True while a save and its choice run (the chooser's other choices wait), false once they end. */
  onBusy: (busy: boolean) => void;
  /** Closes the panel: `used` once the release is in use, false for Cancel. */
  onClose: (used: boolean) => void;
}) {
  const t = useAdminText(), { locale } = useLocalization(), access = useAdminAccess(), client = useQueryClient(), id = useId(), heading = useRef<HTMLHeadingElement>(null);
  // Equals catalogReviewKey (catalogReviewSummaryQuery.ts), so the page's discarded subscription sees this read and one
  // invalidation reads the detail, the summary, the identity rows and this read again.
  const review = ['admin-catalog-reviews', access.viewerId, access.epoch, access.generation, projectId];
  const query = useQuery({ queryKey: [...review, 'pairing', candidateKey, run],
    queryFn: ({ signal }) => adminEndpointRequest(`/catalog-reviews/${projectId}/lookup/candidates/${encodeURIComponent(candidateKey)}/pairing`, pairingSchema, { signal }),
    retry: false, gcTime: 0, refetchOnWindowFocus: false });
  const [picked, setPicked] = useState<Record<string, string> | null>(null), [step, setStep] = useState<Step | null>(null), [phase, setPhase] = useState<Phase>('idle');
  useEffect(() => { heading.current?.focus(); }, []);
  // Reads the review again; once the release is used the panel closes, so its own read is left out.
  const refresh = (closing = false) => { void client.invalidateQueries({ queryKey: review, ...(closing ? { predicate: query => query.queryKey[review.length] !== 'pairing' } : {}) }); };
  // A reload request leaves only Cancel: nothing on this page can pass it.
  const data = query.data, busy = phase === 'saving' || phase === 'choosing', stuck = phase === 'reload', message = said[phase];
  // Before any change a member starts on its forced row (one an earlier member took is skipped), every other on none; a position
  // no longer among a member's options counts as none.
  const choice: Record<string, string> = {};
  for (const member of data?.members ?? []) {
    const value = picked ? picked[member.slotId] ?? '' : member.forced && !Object.values(choice).includes(at(member.forced)) ? at(member.forced) : '';
    choice[member.slotId] = member.options.some(option => at(option) === value) ? value : '';
  }
  const chosen = Object.values(choice).filter(Boolean), remaining = (data?.members.length ?? 0) - chosen.length;
  const current = Boolean(data && data.run === run && data.members.length > 0), idle = !disabled && !busy && !query.isFetching;
  const canSave = current && idle && !stuck && remaining === 0 && new Set(chosen).size === chosen.length;

  // Every member's Disc and Track Number, also an unchanged one, so each becomes the administrator's own and constrains the re-rank;
  // a member whose review captured no Disc Number keeps it as shown (a save refuses any other), so its Track Number alone is sent.
  const save = (value: Pairing) => intent('save', `/catalog-reviews/${projectId}`, 'PATCH', { expectedRevision: value.revision,
    changes: value.members.flatMap(member => {
      const [discNumber, trackNumber] = choice[member.slotId].split(':').map(Number), numbers = { path: `tracks.${member.slotId}.trackNumber`, base: member.saved.track, value: trackNumber };
      return member.discSavable ? [{ path: `tracks.${member.slotId}.discNumber`, base: member.saved.disc, value: discNumber }, numbers] : [numbers];
    }) });
  const choose = (value: Pairing, revision = value.revision) => intent('choose', `/catalog-reviews/${projectId}/lookup/choose`, 'POST', { expectedRevision: revision, run: value.run, candidateKey });
  const send = async (value: Step) => {
    const answer = await adminEndpointRequest(value.path, changed, { method: value.method, body: value.body });
    if (answer.receipt.operationId !== value.operationId || answer.item.id !== projectId) throw new ApiError('Unconfirmed receipt', 'invalid-response');
    return answer.item.revision;
  };
  // One sequence: the save, the lookup read and the choice unless the save's re-rank already applied this pairing. It runs to its
  // end even when the panel closes meanwhile, which only drops its state; the chooser waits until it ends, then closes it.
  async function sequence(first: Step, value: Pairing) {
    let active = first, saved = first.kind === 'choose', used = false;
    // Its button is disabled meanwhile, which would drop focus out of the panel, so focus moves to the heading.
    heading.current?.focus(); onBusy(true); setStep(first); setPhase(saved ? 'choosing' : 'saving');
    try {
      const revision = await send(active);
      if (!saved) {
        saved = true; setPhase('choosing');
        const { lookup } = await adminEndpointRequest(`/catalog-reviews/${projectId}/lookup`, reread);
        const applied = lookup?.applied, pairs = applied?.pairs;
        const here = applied && applied.run === value.run && applied.candidateKey !== null && editions.includes(applied.candidateKey) && pairs
          && pairs.length === value.members.length && pairs.every(pair => choice[pair.slotId] === `${pair.discNumber}:${pair.trackNumber}`);
        if (!here) {
          const candidate = lookup?.run === value.run ? lookup.candidates.find(item => item.key === candidateKey) : undefined;
          if (candidate?.comparison?.subset?.pairing !== 'unique') { refresh(); setStep(null); setPhase('notSingle'); return; }
          active = choose(value, revision); setStep(active);
          await send(active);
        }
      }
      refresh(true); used = true;
    } catch (error) {
      const unconfirmed = !definite(error);
      if (!unconfirmed || saved) refresh();
      // An unconfirmed outcome keeps the same intent, so sending it again replays what the server stored; a definite refusal starts
      // over from the review read again (its revision and saved numbers).
      setStep(unconfirmed && active.kind === (saved ? 'choose' : 'save') ? active : null);
      setPhase(reload(error) ? 'reload' : saved ? unconfirmed ? 'chooseUnknown' : 'chooseFailed' : unconfirmed ? 'saveUnknown' : 'saveFailed');
    } finally { onBusy(false); }
    if (used) onClose(true);
  }
  // A changed choice is a new intent: a kept one would send the earlier choices.
  const select = (slotId: string, value: string) => {
    setPicked({ ...choice, [slotId]: value }); setStep(null);
    if (phase !== 'idle') setPhase('idle');
  };

  const rows = new Map((data?.rows ?? []).map(row => [at(row), row]));
  const seconds = new Intl.NumberFormat(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const length = (ms: number | null, member = false) => ms === null ? t('catalog_review.pairing_duration_unknown') : clock(ms, member);
  const delta = (ms: number | null) => ms === null ? null : ms < 5 ? t('catalog_review.pairing_same_duration') : t('catalog_review.pairing_delta', { seconds: seconds.format(ms / 1000) });
  // An outcome left unconfirmed (its intent kept) may have been stored, so Cancel has the page read the review again.
  const cancel = <button type="button" className={styles.button} disabled={busy} onClick={() => { if (step) refresh(true); onClose(false); }}>{t('common.cancel')}</button>;
  const primary = `${styles.button} ${styles.primary}`;
  // A third-level heading, as the chooser's sections and the summary's other parts have, so it follows the lookup panel's heading in
  // order whichever view of the chooser it follows.
  return <section aria-labelledby={`${id}-title`} className={styles.panel}>
    <h3 id={`${id}-title`} tabIndex={-1} ref={heading}>{data ? t('catalog_review.pairing_title', { title, rows: data.rows.length, discs: new Set(data.rows.map(row => row.disc)).size })
      : t('catalog_review.lookup_pair_by_hand')}</h3>
    {query.isPending ? <p role="status">{t('common.loading')}</p>
      : query.isError || !data ? <><p role="alert">{t('catalog_review.pairing_load_error')}</p>
        <div className={styles.actions}><button type="button" className={styles.button} disabled={query.isFetching} onClick={() => void query.refetch()}>{t('common.retry')}</button>{cancel}</div></>
      : data.run !== run ? <><p role="status">{t('common.lookup_stale')}</p><div className={styles.actions}>{cancel}</div></>
      : <>
        <p>{t('catalog_review.pairing_copy')}</p>
        <ol className={styles.entries}>{data.members.map((member, index) => {
          const forced = member.forced && rows.get(at(member.forced)), field = `${id}-${index}`;
          return <li key={member.slotId} className={styles.field}>
            <label htmlFor={field}>{`${index + 1} · ${member.title || '—'} · ${length(member.durationMs, true)}`}</label>
            <select id={field} className={styles.input} value={choice[member.slotId]} disabled={disabled || busy || stuck} aria-describedby={forced ? `${field}-forced` : undefined}
              onChange={event => select(member.slotId, event.target.value)}>
              <option value="">{t('catalog_review.pairing_choose_track')}</option>
              {member.options.map(option => {
                const row = rows.get(at(option))!, taken = data.members.findIndex(other => other !== member && choice[other.slotId] === at(option));
                return <option key={at(option)} value={at(option)} disabled={taken >= 0}>{[`${option.disc}-${option.track} ${row.title}`, length(row.durationMs), delta(option.deltaMs),
                  taken >= 0 && t('catalog_review.pairing_taken', { track: taken + 1 })].filter(Boolean).join(' · ')}</option>;
              })}
            </select>
            {forced && <p className={styles.muted} id={`${field}-forced`}>{t('catalog_review.pairing_forced', { position: `${forced.disc}-${forced.track}`, title: forced.title })}</p>}
          </li>;
        })}</ol>
        <p className={styles.muted}>{t('catalog_review.pairing_outcome', { missing: Math.max(0, data.rows.length - data.members.length) })}</p>
        {remaining > 0 && <p className={styles.muted}>{t('catalog_review.pairing_remaining', { count: remaining })}</p>}
        <div className={styles.actions}>
          {phase === 'chooseFailed' || phase === 'chooseUnknown' ? <button type="button" className={primary} disabled={!current || !idle}
            onClick={() => void sequence(step?.kind === 'choose' ? step : choose(data), data)}>{t('lookup.choose')}</button>
            : <button type="button" className={primary} disabled={!canSave} onClick={() => void sequence(step?.kind === 'save' ? step : save(data), data)}>{t('catalog_review.pairing_save')}</button>}
          {cancel}
        </div>
        <p role="status">{message && t(message)}</p>
      </>}
  </section>;
}
